  (* [comment removed for export] *)
  Lemma pcp_F1 : forall regs m (s : Z),
    rdn SEGS m (Z_to_bv 64 0x38470) 8 = Some (Z_to_le_bytes 8 0x394e0) -> rdn SEGS m (Z_to_bv 64 0x394e0) 4 = Some (Z_to_le_bytes 4 3) ->
    getr regs 2 = Z_to_bv 64 (s - 48) -> getr regs 10 = Z_to_bv 64 0 ->
    exists regs',
      msteps SEGS (mkst regs (0x19d64 : word) m rom) (mkst regs' (0x17c74 : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 48) /\ getr regs' 1 = Z_to_bv 64 0x19dd4
      /\ getr regs' 10 = Z_to_bv 64 0x10758 /\ getr regs' 11 = Z_to_bv 64 0x117ca /\ getr regs' 12 = Z_to_bv 64 0 /\ getr regs' 19 = Z_to_bv 64 0x394e0
